function countSubarraysWithSum(nums, k) {
  const freq = new Map(); // prefixSum -> berapa kali muncul
  let count = 0;
  let prefix = 0;
  freq.set(0, 1); // prefix kosong sebelum index 0
  for (const x of nums) {
    prefix += x;
    count += freq.get(prefix - k) || 0;
    freq.set(prefix, (freq.get(prefix) || 0) + 1);
  }
  return count;
}
